// n8n Code node "Build Claude request" (Run Once for Each Item)
// Input: the Webhook item, with the log at body.raw_log.
// Output: { request } for the HTTP Request node to send as its JSON body.
// build.mjs fills in SYSTEM_PROMPT and SCHEMA from system-prompt.txt and schema.json
// when it writes workflow.json. Edit those files, not the copy in workflow.json.
const SYSTEM_PROMPT = "You are a telemetry ingestion parser. You receive one raw daily log (typed notes, biometric readings, voice-note transcripts, workout notes) and return a single JSON object that matches the supplied schema.\n\nRules:\n1. Extract only what the log states. If a value is not stated, return null for it. Never estimate, average, or carry values over from general knowledge.\n2. Numbers are numbers. Drop unit words (\"kg\", \"steps\", \"bpm\", \"g\", \"kcal\"). Body weight and lifted weight go in kilograms: if the log gives pounds, convert (1 lb = 0.4536 kg) and round to one decimal. If no unit is given, assume kilograms.\n3. timestamp: an ISO 8601 date-time only if the log states the date or time of the entry; otherwise null. Do not use today's date.\n4. training: one object per exercise, in the order the log mentions them. Put the movement name in exercise. If sets or reps are not stated (for example a timed hold or a run), return null for them and describe what was done in notes. Bodyweight movements have weight_kg null unless added load is stated.\n5. nutrition.protocol is the eating approach the log names (for example \"18:6\", \"OMAD\", \"refeed\", \"72h fast\"). adherence is true or false only when the log says whether the plan was followed.\n6. flags: short plain statements of anything the log reports as a problem: fatigue, poor sleep, pain or injury, missed sessions, broken fasts, strength dropping, illness. Use an empty array when there are none.";
const SCHEMA = {
  "type": "object",
  "properties": {
    "timestamp": {
      "type": [
        "string",
        "null"
      ],
      "format": "date-time"
    },
    "biometrics": {
      "type": "object",
      "properties": {
        "body_weight_kg": {
          "type": [
            "number",
            "null"
          ]
        },
        "step_count": {
          "type": [
            "integer",
            "null"
          ]
        },
        "resting_heart_rate": {
          "type": [
            "integer",
            "null"
          ]
        },
        "sleep_hours": {
          "type": [
            "number",
            "null"
          ]
        }
      },
      "required": [
        "body_weight_kg",
        "step_count",
        "resting_heart_rate",
        "sleep_hours"
      ],
      "additionalProperties": false
    },
    "nutrition": {
      "type": "object",
      "properties": {
        "protocol": {
          "type": [
            "string",
            "null"
          ]
        },
        "total_calories": {
          "type": [
            "integer",
            "null"
          ]
        },
        "protein_grams": {
          "type": [
            "integer",
            "null"
          ]
        },
        "adherence": {
          "type": [
            "boolean",
            "null"
          ]
        }
      },
      "required": [
        "protocol",
        "total_calories",
        "protein_grams",
        "adherence"
      ],
      "additionalProperties": false
    },
    "training": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "exercise": {
            "type": "string"
          },
          "weight_kg": {
            "type": [
              "number",
              "null"
            ]
          },
          "sets": {
            "type": [
              "integer",
              "null"
            ]
          },
          "reps": {
            "type": [
              "integer",
              "null"
            ]
          },
          "notes": {
            "type": [
              "string",
              "null"
            ]
          }
        },
        "required": [
          "exercise",
          "weight_kg",
          "sets",
          "reps",
          "notes"
        ],
        "additionalProperties": false
      }
    },
    "flags": {
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  },
  "required": [
    "timestamp",
    "biometrics",
    "nutrition",
    "training",
    "flags"
  ],
  "additionalProperties": false
};

const rawLog = String($input.item.json.body?.raw_log ?? '').trim();
if (!rawLog) {
  throw new Error('body.raw_log is empty');
}

return {
  json: {
    raw_log: rawLog,
    request: {
      model: 'claude-opus-5-5',
      max_tokens: 16000,
      output_config: {
        effort: 'low',
        format: { type: 'json_schema', schema: SCHEMA },
      },
      fallbacks: 'default',
      system: SYSTEM_PROMPT,
      messages: [
        {
          role: 'user',
          content: `Extract the telemetry from this log:\n\n<log>\n${rawLog}\n</log>`,
        },
      ],
    },
  },
};

// n8n Code node "Parse Claude response" (Run Once for Each Item)
// Input: the HTTP Request node's output (the raw Messages API response).
// The response can hold thinking and fallback blocks before the text, so
// find the text block instead of reading content[0].
const res = $input.item.json;
const ingestedAt = new Date().toISOString();

function fail(error, extra = {}) {
  return {
    json: {
      success: false,
      error,
      stop_reason: res.stop_reason ?? null,
      model: res.model ?? null,
      ...extra,
      ingested_at: ingestedAt,
    },
  };
}

if (res.type === 'error' || res.error) {
  return fail(`API error: ${res.error?.type ?? 'unknown'}: ${res.error?.message ?? ''}`);
}
if (res.stop_reason === 'refusal') {
  return fail('Claude declined the request', { stop_details: res.stop_details ?? null });
}
if (res.stop_reason === 'max_tokens') {
  return fail('Output hit max_tokens and is incomplete');
}

const text = (res.content ?? [])
  .filter((block) => block.type === 'text')
  .map((block) => block.text)
  .join('')
  .trim();

try {
  const data = JSON.parse(text);
  return {
    json: {
      success: true,
      data,
      model: res.model,
      usage: res.usage ?? null,
      ingested_at: ingestedAt,
    },
  };
} catch (error) {
  return fail('JSON parsing failed', { raw_output: text });
}
